import os
os.environ.setdefault("PYTORCH_ENABLE_MPS_FALLBACK", "1")

import cv2
import numpy as np
from ultralytics import YOLO

try:
    import torch
except:
    torch = None

YOLO_DRIVING_CLASS_NAMES = (
    "person",
    "bicycle",
    "car",
    "motorcycle",
    "bus",
    "truck",
    "traffic light",
    "stop sign",
)


def yolo_select_device():
    if torch is not None:
        try:
            if torch.backends.mps.is_available():
                return "mps"
        except:
            pass
        try:
            if torch.cuda.is_available():
                return "cuda"
        except:
            pass
    return "cpu"


def yolo_model_and_classes(state, weights):
    model_key = "model:" + weights
    class_key = "classes:" + weights
    model = state.get(model_key)
    if model is None:
        model = YOLO(weights)
        state[model_key] = model
        class_ids = []
        try:
            for class_id, class_name in model.names.items():
                if str(class_name) in YOLO_DRIVING_CLASS_NAMES:
                    class_ids.append(int(class_id))
        except:
            class_ids = []
        state[class_key] = class_ids
    return model, state.get(class_key) or []


def ros_image_to_bgr(img):
    data = img.get("data") or []
    fmt = str(img.get("format") or "").lower()
    if fmt or not img.get("height"):
        try:
            arr = np.frombuffer(data, dtype=np.uint8)
        except:
            arr = np.asarray(data, dtype=np.uint8)
        if arr.size <= 0:
            return None
        return cv2.imdecode(arr, cv2.IMREAD_COLOR)

    h = int(img.get("height") or 0)
    w = int(img.get("width") or 0)
    enc = str(img.get("encoding") or "rgb8").lower()
    if h <= 0 or w <= 0:
        return None
    channels = 3
    if enc == "mono8":
        channels = 1
    if enc == "rgba8" or enc == "bgra8":
        channels = 4
    try:
        arr = np.frombuffer(data, dtype=np.uint8)
    except:
        arr = np.asarray(data, dtype=np.uint8)
    needed = h * w * channels
    if arr.size < needed:
        return None
    arr = arr[:needed].reshape((h, w, channels))
    if enc == "rgb8":
        return cv2.cvtColor(arr, cv2.COLOR_RGB2BGR)
    if enc == "rgba8":
        return cv2.cvtColor(arr, cv2.COLOR_RGBA2BGR)
    if enc == "bgra8":
        return cv2.cvtColor(arr, cv2.COLOR_BGRA2BGR)
    if enc == "mono8":
        return cv2.cvtColor(arr, cv2.COLOR_GRAY2BGR)
    return arr.copy()


def bgr_to_ros_image(bgr):
    if bgr is None:
        return None
    if len(bgr.shape) == 2:
        rgb = cv2.cvtColor(bgr, cv2.COLOR_GRAY2RGB)
    else:
        rgb = cv2.cvtColor(bgr, cv2.COLOR_BGR2RGB)
    rgb = np.ascontiguousarray(rgb, dtype=np.uint8)
    h, w = rgb.shape[:2]
    return {
        "height": int(h),
        "width": int(w),
        "encoding": "rgb8",
        "is_bigendian": 0,
        "step": int(w * 3),
        "data": rgb.tobytes(),
    }


def yolo_overlay(state, img, weights, conf, imgsz):
    bgr = ros_image_to_bgr(img)
    if bgr is None:
        return None
    device = state.get("device")
    if not device:
        device = yolo_select_device()
        state["device"] = device
    if not state.get("device_logged"):
        state["device_logged"] = True
        print("YOLO device:", device)
    model, class_ids = yolo_model_and_classes(state, weights)
    options = {
        "imgsz": int(imgsz),
        "conf": float(conf),
        "device": device,
        "verbose": False,
    }
    if class_ids:
        options["classes"] = class_ids
    results = model.predict(bgr, **options)
    if not results:
        return bgr_to_ros_image(bgr)
    annotated = results[0].plot()
    return bgr_to_ros_image(annotated)
